/**
 * Production error workflow payload (Settings → Error Workflow).
 * Link this workflow from the main JMT-S governed workflow.
 */
const item = $input.first().json;
const err = item.execution?.error ?? {};
const failedNode = err.node?.name ?? item.execution?.lastNodeExecuted ?? 'unknown node';
const message = err.message ?? err.description ?? 'Workflow failed';

return [{
  json: {
    failure_summary: String(failedNode) + ': ' + String(message).slice(0, 450),
    external_execution_id: String(item.execution?.id ?? ''),
    failed_workflow: item.workflow?.name ?? '',
  },
}];
